    /// <summary>Visits node <paramref name="id"/> (non-zero) through its kind's hook if overridden, else walks its children.</summary>
    /// <remarks>
    /// Identifiers (about half of all nodes) are handled without the indirect call, and so are leaf kinds this
    /// visitor does not override (literals, this, ...), which have nothing to do.
    /// </remarks>
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    internal static void Walk(AstVisitor v, JsAst ast, int id)
    {
        NodeKind kind = ast._nodes[id].Kind;
        if (kind == NodeKind.Identifier)
        {
            if (v.Ov((int)NodeKind.Identifier)) v.CallVisitIdentifier(ast, id);
            return;
        }
        if (v.Skip(kind)) return;
        s_walkers[(int)kind](v, ast, id);
    }

    private static void WalkNone(AstVisitor v, JsAst ast, int id) { }

    private static void WalkProgram(AstVisitor v, JsAst ast, int id)
    {
        byte probe;
        if ((nuint)((nint)(&probe) - v._stackLimit) >= StackWindow && v.StackIsLow()) { v.WalkOnNewStack(ast, id); return; }
        if (v.Ov((int)NodeKind.Program)) { v.CallVisitProgram(ast, id); return; }
        WalkChildrenOfProgram(v, ast, id);
    }

